// player.js —— 玩家控制：WASD/方向键移动、撞墙与边界钳制、相机跟随、空格挥剑、拾取金币。
// 全局变量统一 P_ 前缀：脚本之间共享同一个 bwe 全局，前缀能避免撞名（docs/scripting-api.md §1）。
var P_CFG = {
  speed: 190,          // 像素/秒
  half: 10,            // 碰撞半宽（像素）
  attackRange: 76,
  attackDamage: 12,
  attackCooldown: 0.45,
  coinRadius: 24
};

var P_STATE = {
  ready: false,
  cool: 0,
  gold: 0,
  moved: false,
  attacks: 0,
  // 在 onStart 里按地图尺寸填；提前声明这两个字段，编辑器的类型检查才能推断出来
  // （否则 P_STATE 会被推断成字面量类型，赋值 mapW/mapH 会报「属性不存在」）。
  mapW: 0,
  mapH: 0
};

function onStart(ctx) {
  var map = bwe.world.mapSize();
  P_STATE.mapW = map.w;
  P_STATE.mapH = map.h;
  // 相机交给脚本（文档 §2.4）：平滑跟随 + 限制在地图内。
  bwe.camera.follow(ctx.self, { smooth: 0.18 });
  bwe.camera.bounds({ x: 0, y: 0, w: map.w, h: map.h });
  P_STATE.ready = true;
  bwe.log("[脚本] player ready：地图 " + map.w + "x" + map.h + "（WASD 移动 / 空格挥剑 / E 交互）");
}

function onUpdate(ctx, dt) {
  var me = ctx.self;
  if (!P_STATE.ready || !me || me.alive === false) return;
  if (P_STATE.cool > 0) P_STATE.cool = Math.max(0, P_STATE.cool - dt);
  move(me, dt);
  if (bwe.input.pressed("Space") || bwe.input.pressed("KeyJ")) swing(me);
  collectCoins(me);
}

function move(me, dt) {
  var axis = bwe.input.axis(); // 已归一化：WASD 与方向键都算（文档 §2.3）
  if (!axis || (axis.x === 0 && axis.y === 0)) return;
  if (!P_STATE.moved) {
    P_STATE.moved = true;
    bwe.log("[脚本] player 开始移动");
  }
  var step = P_CFG.speed * dt;
  var nx = me.x + axis.x * step;
  var ny = me.y + axis.y * step;
  // 撞墙：分两个轴判，贴墙时还能沿墙滑（bwe.tilemap.blocked 是像素 AABB）
  if (!solid(nx, me.y)) me.setPos(nx, me.y);
  if (!solid(me.x, ny)) me.setPos(me.x, ny);
  clampToMap(me);
}

function solid(x, y) {
  var h = P_CFG.half;
  return bwe.tilemap.blocked(x - h, y - h, h * 2, h * 2);
}

function clampToMap(me) {
  var h = P_CFG.half;
  var x = Math.max(h, Math.min(P_STATE.mapW - h, me.x));
  var y = Math.max(h, Math.min(P_STATE.mapH - h, me.y));
  if (x !== me.x || y !== me.y) me.setPos(x, y);
}

function swing(me) {
  if (P_STATE.cool > 0) return;
  P_STATE.cool = P_CFG.attackCooldown;
  P_STATE.attacks += 1;
  bwe.camera.shake(3, 0.12);
  var list = enemies(me);
  var hit = 0;
  for (var i = 0; i < list.length; i++) {
    if (me.distanceTo(list[i]) <= P_CFG.attackRange) {
      list[i].damage(P_CFG.attackDamage);
      hit += 1;
    }
  }
  bwe.log("[脚本] 玩家挥剑（第 " + P_STATE.attacks + " 次），命中 " + hit + " 个敌人");
}

function collectCoins(me) {
  var coins = bwe.world.findAll({ tag: "金币" }) || [];
  for (var i = 0; i < coins.length; i++) {
    var coin = coins[i];
    if (!coin || coin.alive === false) continue;
    if (me.distanceTo(coin) > P_CFG.coinRadius) continue;
    bwe.world.destroy(coin);
    P_STATE.gold += 1;
    bwe.save.set("gold", P_STATE.gold);
    bwe.world.emit("gold", { gold: P_STATE.gold });
    bwe.log("[脚本] 拾取金币 x" + P_STATE.gold);
  }
}

// 追击怪识别：标签 / 名字 / props.enemy 三选一都算。
// 为什么要有 props.enemy：bwe.spawner.create 刷出来的实体没有 tags 也没有名字，
// chaser.js 在 onStart 里给自己 setProp("enemy", "1") 打标记，这里就能认出来。
function enemies(me) {
  var all = bwe.world.entities() || [];
  var out = [];
  for (var i = 0; i < all.length; i++) {
    var e = all[i];
    if (!e || e.alive === false || e.id === me.id) continue;
    var byTag = e.tags && typeof e.tags.includes === "function" ? e.tags.includes("敌人") : false;
    var byName = !!(e.name && e.name.indexOf("追击怪") >= 0);
    var byProp = String(e.prop("enemy", "")) === "1";
    if (byTag || byName || byProp) out.push(e);
  }
  return out;
}

function onDamage(ctx, amount, from) {
  bwe.log("[脚本] 玩家受击 -" + Math.round(amount));
  bwe.camera.shake(5, 0.2);
}

function onDeath(ctx, by) {
  bwe.log("[脚本] 玩家阵亡，金币归零");
  bwe.world.emit("gameover", {});
}

